import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.BQGW-Zpy.js";const u=JSON.parse('{"title":"Regulatory Landscape","description":"","frontmatter":{},"headers":[],"relativePath":"legal/regulatory-landscape.md","filePath":"legal/regulatory-landscape.md"}'),i={name:"legal/regulatory-landscape.md"};function r(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="regulatory-landscape" tabindex="-1">Regulatory Landscape <a class="header-anchor" href="#regulatory-landscape" aria-label="Permalink to &quot;Regulatory Landscape&quot;">​</a></h1><p><em>Verified as of mid-2026, this space moves monthly; re-check before relying on any specific date below.</em></p><table tabindex="0"><thead><tr><th>Milestone</th><th>Date</th><th>Effect</th></tr></thead><tbody><tr><td>MiCA transitional regime ended</td><td>1 Jul 2026</td><td>Any provider offering crypto-asset services to EU clients now needs full CASP authorisation</td></tr><tr><td>EBA No-Action Letter transition ended</td><td>2 Mar 2026</td><td>Transferring e-money tokens (EMTs) on behalf of clients is a <strong>payment service under PSD2</strong></td></tr><tr><td>EBA position on custodial wallets</td><td>2026</td><td>A custodial wallet allowing clients to send/receive EMTs is a <strong>payment account</strong> under PSD2</td></tr></tbody></table><h2 id="the-three-post-march-2026-scenarios" tabindex="-1">The three post-March-2026 scenarios <a class="header-anchor" href="#the-three-post-march-2026-scenarios" aria-label="Permalink to &quot;The three post-March-2026 scenarios&quot;">​</a></h2><p>After the dual-licensing regime took effect, a firm transacting EMTs has three options:</p><ol><li>Obtain its own PI/EMI authorisation on top of a MiCA CASP licence</li><li><strong>Partner with an authorised PSP</strong>, the agency model</li><li>Exit the market</li></ol><p>This project is scenario 2, see <a href="./why-this-is-legal.html">Why This Is Legal</a>.</p><h2 id="stablecoin-compliance" tabindex="-1">Stablecoin compliance <a class="header-anchor" href="#stablecoin-compliance" aria-label="Permalink to &quot;Stablecoin compliance&quot;">​</a></h2><p><strong>USDT is not MiCA-compliant</strong>, delisted from major EU venues, and Tether has stated no intention to pursue authorisation. <strong>USDC and EURC (Circle) are the only MiCA-authorised EMTs with meaningful liquidity.</strong> This is a hard design constraint, not a preference, see <code>COMPLIANT_STABLECOIN_CHAINS</code> in <code>corridorConfig.mjs</code>.</p><h2 id="the-public-sector-context" tabindex="-1">The public-sector context <a class="header-anchor" href="#the-public-sector-context" aria-label="Permalink to &quot;The public-sector context&quot;">​</a></h2><p>This problem has been on the G20 agenda since 2020 (the <em>Roadmap for Enhancing Cross-border Payments</em>), with quantitative targets for end-2027. By the BIS&#39;s own assessment, jurisdictional implementation has been uneven and it&#39;s unlikely those targets will be met, which is the gap a private, non-custodial layer like this one occupies, not a competition with the public rails (Nexus, Agorá, Mandala) themselves.</p>',11)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
